export const OptionsButton: FC = () => {
    const visType = useAppSelector(getVisUiConfigVisualizationType)

    const [isOptionsModalOpen, setIsOptionsModalOpen] = useState<boolean>(false)

    const toggleOptionsModal = useCallback(
        () => setIsOptionsModalOpen((currentIsOpen) => !currentIsOpen),
        []
    )

    const buttonLabel = useMemo(() => {
        switch (visType) {
            case 'LINE_LIST':
                return i18n.t('List options')
            case 'PIVOT_TABLE':
                return i18n.t('Table options')
            default:
                return i18n.t('Chart options')
        }
    }, [visType])

    const onClose = useCallback(
        () => setIsOptionsModalOpen(false),
        [setIsOptionsModalOpen]
    )

    return (
        <>
            <Button
                icon={<IconOptions />}
                className={classes.button}
                small
                secondary
                onClick={toggleOptionsModal}
                dataTest="visualization-options-button"
            >
                {buttonLabel}
            </Button>
            {isOptionsModalOpen && <OptionsModal onClose={onClose} />}
        </>
    )
}
